#include "image_export.h"
#include "image_decode.h"
#include <windows.h>
#include <iostream>
using namespace moon;
void check(bool value,const char* message){if(!value)throw std::runtime_error(message);}
int main(){try{const auto owned=std::filesystem::path("jpeg-test-owned")/(std::to_string(GetCurrentProcessId())+"-"+std::to_string(GetTickCount64()));std::filesystem::create_directories(owned);
 const Pixel cases[]{0x003c28ff,0x800000ff,0xff0000ff,0x00ffffff,0x25d95c12};const Pixel expected[]{0xff000000,0xff000080,0xff0000fe,0xff000000,0xff1f0c04};
 for(int n=0;n<5;++n){auto out=encodeImageJpeg(16,16,std::vector<Pixel>(256,cases[n]));auto file=owned/(std::to_string(n)+".jpg");writeExportBytesAtomic(file,out.bytes);auto decoded=openRasterImage(file);check(decoded.width()==16&&decoded.height()==16,"JPEG dimensions");const auto pixel=decoded.pixels()[8*16+8];for(int c=0;c<3;++c)check(std::abs(int((pixel>>(8*c))&255)-int((expected[n]>>(8*c))&255))<=2,"JPEG alpha/quality differs from actual Chromium sample");check(pixel>>24==255,"JPEG not opaque");std::cout<<n<<":"<<std::hex<<pixel<<std::dec<<"\n";}
 Document document=Document::fromImage(2,2,{0xff0000ff,0,0,0xff00ff00},U"fixture");document.markSaved();const auto history=document.historySize(),revision=document.revision();const auto pixels=document.pixels();StaticImageExportOptions options;options.scalePercent=200;options.trim=true;auto output=encodeStaticImageJpeg(document,options);check(output.width==4&&output.height==4,"JPEG prepare scale");check(document.historySize()==history&&document.revision()==revision&&!document.dirty(),"JPEG scale mutated history");document.commitSelection({},SelectionMask{0,0,1,1,{}});options.selection=true;output=encodeStaticImageJpeg(document,options);check(output.width==2&&output.height==2,"JPEG selection prepare");document.deselectPixels();options.selection=false;options.scalePercent=400;options.protection=ExportProtection::Blur;const auto finalHistory=document.historySize(),finalRevision=document.revision();const auto finalDirty=document.dirty();output=encodeStaticImageJpeg(document,options);check(output.width==8&&output.height==8,"JPEG protection dimensions");check(document.pixels()==pixels&&document.historySize()==finalHistory&&document.revision()==finalRevision&&document.dirty()==finalDirty,"JPEG source mutation");
 bool invalid=false;try{encodeImageJpeg(1,2,{});}catch(...){invalid=true;}check(invalid,"JPEG invalid pixels accepted");std::cout<<"JPEG original Chromium alpha samples / admitted prepare checks passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}}
